SELECT a.id, a.uuid, a.business_type AS businessType, a.business_uuid AS businessUuid, a.file_name AS fileName, a.original_file_name AS originalFileName, a.file_ext AS fileExt, a.mime_type AS mimeType, a.file_size AS fileSize, a.storage_path AS storagePath, a.uploaded_by AS uploadedBy, u.real_name AS uploadedByName, u.username AS uploadedByUsername, a.uploaded_at AS uploadedAt FROM attachment a LEFT JOIN sys_user u ON u.id = a.uploaded_by WHERE a.business_type = #{param1}
AND a.business_uuid = #{param2}
ORDER BY a.uploaded_at DESC, a.id DESC

mapper.update:
UPDATE attachment
business_type = #{businessType}, business_uuid = #{businessUuid}, file_name = #{fileName}, original_file_name = #{originalFileName}, file_ext = #{fileExt}, mime_type = #{mimeType}, file_size = #{fileSize}, storage_path = #{storagePath}, uploaded_by = #{uploadedBy}, uploaded_at = NOW()
WHERE uuid = #{uuid}
